    /** Daftar seri milik satu brand (UUID). */
    export function getBatch3SeriByBrandId(brandId: string): ProdukKomersialBatch3Seri[] {
    return PK_BATCH3_SERI_LIST.filter(s => s.brandId === brandId);
    }

    /** Lookup satu seri via brandId + seriSlug (routing). */
    export function getBatch3SeriBySlug(brandId: string, seriSlug: string): ProdukKomersialBatch3Seri | undefined {
    return PK_BATCH3_SERI_LIST.find(s => s.brandId === brandId && s.slug === seriSlug);
    }

    /** Lookup seri via UUID. */
    export function getBatch3SeriByUUID(uuid: string): ProdukKomersialBatch3Seri | undefined {
    return PK_BATCH3_SERI_LIST.find(s => s.uuid === uuid);
    }
    